      "keystrokes": "mkdir -p /etc/ssh/sshd_config.d\ncat > /etc/ssh/sshd_config.d/99-git.conf <<'EOF'\nPasswordAuthentication yes\nPubkeyAuthentication yes\nEOF\n",
      "duration": 0.3
    },
    {
      "keystrokes": "mkdir -p /run/sshd && /usr/sbin/sshd && nginx -t && nginx\n",
      "duration": 1.5
    },
    {
      "keystrokes": "cd /tmp && rm -rf seed && git init -q -b main seed && cd seed && git config user.email t@t && git config user.name t && echo '<h1>MAIN</h1>' > index.html && git add index.html && git commit -qm main && git checkout -q -b dev && echo '<h1>DEV</h1>' > index.html && git add index.html && git commit -qm dev && git push -q /git/project main && git push -q /git/project dev && cd / && rm -rf /tmp/seed\n",
      "duration": 2.0
    },
    {
      "keystrokes": "chown -R git:git /git /var/www\n",
      "duration": 0.3
    },
    {
      "keystrokes": "ss -tln 2>/dev/null | grep -E ':22|:8443'; echo '--- procs ---'; ps -ef | grep -v grep | grep -E 'sshd|nginx' | wc -l; echo '--- MAIN ---'; curl -sk https://localhost:8443/index.html; echo '--- DEV ---'; curl -sk https://localhost:8443/dev/index.html\n",
      "duration": 1.0
    }
  ]
}

